import{_ as a,c as e,o as r,a5 as o}from"./chunks/framework.DorIfSpC.js";const d=JSON.parse('{"title":"星智未來","description":"星智未來專注於 AI 應用工程，分享 AI、機器人、LLM 實戰筆記與專案故事，以工程實踐創造價值。","frontmatter":{"layout":"home","title":"星智未來","description":"星智未來專注於 AI 應用工程，分享 AI、機器人、LLM 實戰筆記與專案故事，以工程實踐創造價值。","hero":{"name":"星智未來","text":"以 AI 工程，快速把點子變成價值","tagline":"我們分享實戰筆記、專案故事與教學，持續更新。","actions":[{"theme":"brand","text":"AI 文章","link":"/ai/"},{"theme":"alt","text":"機器人文章","link":"/robot/"},{"theme":"alt","text":"專案文章","link":"/project/"}]},"features":[{"title":"AI","details":"最新 AI 技術與應用分享。","link":"/ai/"},{"title":"機器人","details":"機器人最新發展","link":"/robot/"},{"title":"專案","details":"我們的專案展示與經驗分享。","link":"/project/"},{"title":"學習","details":"長期學習路徑的筆記與心得。","link":"/learning/"}],"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/"}],["meta",{"property":"og:description","content":"星智未來專注於 AI 應用工程，分享 AI、機器人、LLM 實戰筆記與專案故事，以工程實踐創造價值。"}],["meta",{"name":"twitter:description","content":"星智未來專注於 AI 應用工程，分享 AI、機器人、LLM 實戰筆記與專案故事，以工程實踐創造價值。"}],["meta",{"property":"og:title","content":"星智未來 | 星智未來"}],["meta",{"name":"twitter:title","content":"星智未來 | 星智未來"}]]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1786596283000}'),i={name:"index.md"};function n(l,t,p,s,h,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h2 id="📝-最新文章" tabindex="-1">📝 最新文章 <a class="header-anchor" href="#📝-最新文章" aria-label="Permalink to &quot;📝 最新文章&quot;">​</a></h2><h3 id="為什麼每天摸一下貓的頭-是一件宇宙學意義的事" tabindex="-1"><a href="/project/migato-cosmic-ritual">為什麼每天摸一下貓的頭，是一件宇宙學意義的事</a> <a class="header-anchor" href="#為什麼每天摸一下貓的頭-是一件宇宙學意義的事" aria-label="Permalink to &quot;[為什麼每天摸一下貓的頭，是一件宇宙學意義的事](/project/migato-cosmic-ritual)&quot;">​</a></h3><p><strong>專案</strong> · 2026-03-20</p><p>從易經到塔羅，人類花了三千年設計觀測工具。Migato 米果把這套古老的儀式，變成每天早上摸一下頭的動作——讓你帶著意圖出門。</p><hr><h3 id="為什麼我花兩美金租-gpu-而不是花十二萬買一張" tabindex="-1"><a href="/project/minimax-h3-third-path">為什麼我花兩美金租 GPU，而不是花十二萬買一張</a> <a class="header-anchor" href="#為什麼我花兩美金租-gpu-而不是花十二萬買一張" aria-label="Permalink to &quot;[為什麼我花兩美金租 GPU，而不是花十二萬買一張](/project/minimax-h3-third-path)&quot;">​</a></h3><p><strong>專案</strong> · 2026-08-13</p><p>MiniMax H3 開源了，但一張 5090 要十二萬。在 RunPod 上租一個下午、花兩美金，把租來的機器當成自己的地端——買到的不是算力，是看得見內部。</p><hr><h3 id="我的第一個-upwork-proposal" tabindex="-1"><a href="/project/my_first_upwork_post">我的第一個 Upwork Proposal</a> <a class="header-anchor" href="#我的第一個-upwork-proposal" aria-label="Permalink to &quot;[我的第一個 Upwork Proposal](/project/my_first_upwork_post)&quot;">​</a></h3><p><strong>專案</strong> · 2026-07-10</p><p>被 layoff 後，一位有二十五年系統整合經驗的工程師，在 Upwork 投出人生第一封接案提案。記錄如何補齊帳號地基、寫出讓客戶讀懂的提案，重新長回「找食物」的能力。</p><hr><h3 id="中國具身智能的兩條路線-motubrain-vs-自變量" tabindex="-1"><a href="/robot/中國具身智能兩條路線">中國具身智能的兩條路線：MotuBrain vs 自變量</a> <a class="header-anchor" href="#中國具身智能的兩條路線-motubrain-vs-自變量" aria-label="Permalink to &quot;[中國具身智能的兩條路線：MotuBrain vs 自變量](/robot/中國具身智能兩條路線)&quot;">​</a></h3><p><strong>機器人</strong> · 2026-05-14</p><p>生數 MotuBrain 與自變量機器人都選 World Action Model，但商業模式截然相反——純大腦供應商 vs 軟硬一體。一年後回看，誰賭對了路線？</p><hr><h3 id="機器人沒有-mmlu-當-benchmark-還沒有共識的時候-我們該怎麼看「世界第一」" tabindex="-1"><a href="/robot/機器人沒有MMLU">機器人沒有 MMLU：當 Benchmark 還沒有共識的時候，我們該怎麼看「世界第一」？</a> <a class="header-anchor" href="#機器人沒有-mmlu-當-benchmark-還沒有共識的時候-我們該怎麼看「世界第一」" aria-label="Permalink to &quot;[機器人沒有 MMLU：當 Benchmark 還沒有共識的時候，我們該怎麼看「世界第一」？](/robot/機器人沒有MMLU)&quot;">​</a></h3><p><strong>機器人</strong> · 2026-05-14</p><p>機器人領域目前沒有 benchmark 共識——這是個結構性的不成熟狀態，也是整合者的機會窗口。三個問題教你判讀「世界第一」的新聞稿。</p>',20)])])}const u=a(i,[["render",n]]);export{d as __pageData,u as default};
